static void get_paths(void){DWORD n=GetModuleFileNameW(NULL,g_exe_dir,(DWORD)(sizeof(g_exe_dir)/sizeof(g_exe_dir[0])));if(!n||n>=sizeof(g_exe_dir)/sizeof(g_exe_dir[0]))return;PathRemoveFileSpecW(g_exe_dir);swprintf(g_web_folder,sizeof(g_web_folder)/sizeof(g_web_folder[0]),L"%s\\web",g_exe_dir);swprintf(g_cdn_folder,sizeof(g_cdn_folder)/sizeof(g_cdn_folder[0]),L"%s\\web\\cdnjs",g_exe_dir);swprintf(g_runtime_installer,sizeof(g_runtime_installer)/sizeof(g_runtime_installer[0]),L"%s\\MicrosoftEdgeWebView2RuntimeInstallerX64.exe",g_exe_dir);}
