static HRESULT create_environment(void);
static void install_runtime_and_retry(void){if(g_runtime_retry||GetFileAttributesW(g_runtime_installer)==INVALID_FILE_ATTRIBUTES)return;g_runtime_retry=1;STARTUPINFOW si={0};PROCESS_INFORMATION pi={0};si.cb=sizeof(si);wchar_t cmd[MAX_PATH*2+64];swprintf(cmd,sizeof(cmd)/sizeof(cmd[0]),L"\"%s\" /silent /install",g_runtime_installer);if(CreateProcessW(NULL,cmd,NULL,NULL,FALSE,0,NULL,g_exe_dir,&si,&pi)){WaitForSingleObject(pi.hProcess,INFINITE);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);Sleep(1000);create_environment();}else MessageBoxW(g_hwnd,L"无法启动离线 WebView2 Runtime 安装程序。",L"PDF Bubble Annotator",MB_ICONERROR|MB_OK);}
